+// API keys, roles and the audit trail. Roles: viewer reads, cook also does
+// kitchen work, manager does everything (docs/API.md).
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The key record for a bearer `authorization` header value, or null. */
+export function findKey(store, header) {
+  const m = /^Bearer\s+(\S+)$/i.exec(header ?? "");
+  if (!m) return null;
+  return (store.data.apiKeys ?? []).find((k) => k.key === m[1]) ?? null;
+}
+
+/** Throws `forbidden` unless `role` may call `method` on `path`. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  const read = method === "GET" && path !== "/audit";
+  const cook = role === "cook" && COOK_ROUTES.some(([m, re]) => m === method && re.test(path));
+  if (!read && !cook) throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changes data. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit.push({ at, key, method, path, status });
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse();
+}
